#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Repo root + local env file (gitignored). Convex prod is admired-wildebeest-287.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
ENV_FILE="$ROOT/.env.local"
CONVEX_SITE_URL="https://admired-wildebeest-287.convex.site"
CONVEX_CALLBACK="${CONVEX_SITE_URL}/api/auth/callback/google"
CONVEX_DASHBOARD="https://dashboard.convex.dev/t/neel-kumar-17000/prairierun-feed/admired-wildebeest-287"

# Push one env var to Convex production. Records SKIPPED on failure.
set_convex_env() {
  local name="$1" value="$2"
  if ! command -v npx >/dev/null 2>&1; then
    SKIPPED+=("Convex env $name (npx missing; run: npx convex env set $name <value> --prod)")
    warn "npx not found; set $name on Convex manually"
    return 1
  fi
  if (cd "$ROOT" && npx --yes convex env set "$name" "$value" --prod); then
    printf '  %s✓ set%s Convex prod %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  SKIPPED+=("Convex env $name (run: npx convex env set $name <value> --prod)")
  warn "Convex env set failed for $name — you can retry from the dashboard"
  return 1
}

TOTAL_STAGES=6

banner "PrairieRun · Google Auth → Convex"

stage "Google Cloud project"
say "You need one GCP project that owns the Web OAuth client for PrairieRun."
say "End users never create a project — this is a one-time publisher setup."
open_url "https://console.cloud.google.com/projectselector2"
step "Pick the PrairieRun project (or create one, e.g. prairierun)."
step "Stay signed into the Google account that should own the OAuth client."
pause "Press Enter once the project is selected"

stage "OAuth consent screen"
say "Google needs a consent screen before any Sign in with Google button works."
open_url "https://console.cloud.google.com/apis/credentials/consent"
step "If prompted, choose User type: External → Create."
step "App name: PrairieRun"
step "User support email: your email"
step "Developer contact: your email"
step "Save and continue through Scopes (defaults are fine; openid/email/profile are enough)."
step "If the app is in Testing, add yourself under Test users."
step "Back on the summary, Publishing status can stay Testing while you develop."
pause "Press Enter once the consent screen is saved"

stage "Create Web OAuth client"
say "Convex Auth needs a Web application client (not a Chrome extension client)."
say "Redirect URI that must be listed exactly:"
note "  $CONVEX_CALLBACK"
open_url "https://console.cloud.google.com/apis/credentials"
step "Click + Create credentials → OAuth client ID."
step "Application type: Web application."
step "Name: PrairieRun Convex Auth"
step "Authorized JavaScript origins → Add URI:"
note "  $CONVEX_SITE_URL"
step "Authorized redirect URIs → Add URI:"
note "  $CONVEX_CALLBACK"
step "Click Create. Copy the Client ID from the dialog (…apps.googleusercontent.com)."
ask AUTH_GOOGLE_ID "Paste the Client ID:"
if [[ -z "$AUTH_GOOGLE_ID" || "$AUTH_GOOGLE_ID" == "undefined" ]]; then
  warn "Client ID is empty — re-run this wizard after copying it from the dialog."
  exit 1
fi
write_env AUTH_GOOGLE_ID "$AUTH_GOOGLE_ID"
write_env SITE_URL "$CONVEX_SITE_URL"

stage "Copy Client secret"
say "Same OAuth client dialog (or the client's detail page) shows the Client secret."
open_url "https://console.cloud.google.com/apis/credentials"
step "Open the PrairieRun Convex Auth client if the dialog already closed."
step "Copy the Client secret (click the eye / copy icon if hidden)."
ask_secret AUTH_GOOGLE_SECRET "Paste the Client secret:"
if [[ -z "$AUTH_GOOGLE_SECRET" ]]; then
  warn "Client secret is empty — re-run this stage after copying it."
  exit 1
fi
write_env AUTH_GOOGLE_SECRET "$AUTH_GOOGLE_SECRET"

stage "Push credentials to Convex prod"
say "Extension defaults point at admired-wildebeest-287. These three env vars must be set there."
note "Dashboard: $CONVEX_DASHBOARD"
note "Local copies are already in $ENV_FILE"
if confirm "Set AUTH_GOOGLE_ID, AUTH_GOOGLE_SECRET, and SITE_URL on Convex prod now?"; then
  set_convex_env AUTH_GOOGLE_ID "$AUTH_GOOGLE_ID" || true
  set_convex_env AUTH_GOOGLE_SECRET "$AUTH_GOOGLE_SECRET" || true
  set_convex_env SITE_URL "$CONVEX_SITE_URL" || true
else
  SKIPPED+=("Convex env push (run scripts/setup-google-convex-auth.sh again, or npx convex env set … --prod)")
  warn "Skipped Convex push — values remain only in $ENV_FILE"
fi

stage "Smoke-check Google authorize URL"
say "Convex should now mint a Google URL with a real client_id (not undefined)."
if confirm "Run the smoke check against $CONVEX_SITE_URL now?"; then
  local_probe_out=""
  if local_probe_out=$(node -e '
const cloud="https://admired-wildebeest-287.convex.cloud";
const redirect="https://abcdefghijklmnopqrstuvwxyz.chromiumapp.org/convex";
(async()=>{
  const start=await fetch(cloud+"/api/action",{
    method:"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify({path:"auth:signIn",args:{provider:"google",params:{redirectTo:redirect}},format:"json"}),
  }).then(r=>r.json());
  if(start.status!=="success"||!start.value?.redirect){
    console.error("auth:signIn failed:", JSON.stringify(start).slice(0,300));
    process.exit(2);
  }
  const mid=start.value.redirect;
  const r=await fetch(mid,{redirect:"manual"});
  const loc=r.headers.get("location")||"";
  let clientId="";
  try{ clientId=new URL(loc).searchParams.get("client_id")||""; }catch{}
  if(!clientId||clientId==="undefined"||clientId==="null"){
    console.error("FAIL: Google authorize URL still has client_id="+JSON.stringify(clientId));
    console.error("Location:", loc.slice(0,240));
    process.exit(3);
  }
  console.log("OK client_id="+clientId);
})().catch(e=>{ console.error(e); process.exit(1); });
' 2>&1); then
    note "$local_probe_out"
    say "Google Auth → Convex looks configured. Reload the extension and try Sign in with Google."
  else
    warn "Smoke check failed:"
    note "$local_probe_out"
    SKIPPED+=("Smoke check (confirm Convex env vars, wait ~30s, re-run wizard stage or node probe)")
  fi
else
  note "Skipped. Later: reload the extension and click Sign in with Google."
fi

finish
say "Next: chrome://extensions → reload PrairieRun → dashboard → Sign in with Google."
note "Users only sign into their Google account; they never touch GCP or Convex."
